// Linux kernel interface: readdir(2) (Deprecated)

struct old_linux_dirent {
    long d_ino;
    long d_offset;
    unsigned short d_reclen;
    char d_name[256];
};

unsigned int fd; // Directory file descriptor
struct old_linux_dirent dirp;
ssize_t ret;

// Assume SYS_readdir is defined (e.g., 141 on x86_64)
// int readdir(fd, dirp, count)
ret = syscall(SYS_readdir, fd, &dirp, 1);

// Note: 'count' (3rd argument) is ignored; only one entry is read.

if (ret > 0) {
    // Successfully read directory entry into dirp
}
